    total = {"main": 0, "other": 0}
    main_last = 0
    for a in actions:
        op = a.get("op")
        if op == "begin":
            c = norm(a)
            if not txn[c]:
                txn[c] = True
                began[c] = True
                pend[c] = {}
                saves[c] = []
        elif op == "commit":
            c = norm(a)
            if txn[c]:
                flush(pend[c], comm)
                clear_conn(txn, began, pend, saves, c)
        elif op == "rollback":
            c = norm(a)
            if txn[c]:
                clear_conn(txn, began, pend, saves, c)
