def simulate(cand, actions):
    comm = {}
    txn = {"main": False, "other": False}
    began = {"main": False, "other": False}
    pend = {"main": {}, "other": {}}
    saves = {"main": [], "other": []}
    total = {"main": 0, "other": 0}
    main_last = 0
    for a in actions:
        op = a.get("op")
        if op == "begin":
            c = norm(a)
            if not txn[c]:
                txn[c] = True
                began[c] = True
                pend[c] = {}
                saves[c] = []
        elif op == "commit":
            c = norm(a)
            if txn[c]:
                flush(pend[c], comm)
                clear_conn(txn, began, pend, saves, c)
        elif op == "rollback":
            c = norm(a)
            if txn[c]:
                clear_conn(txn, began, pend, saves, c)
        elif op == "savepoint":
            c = route(a, txn)
            if not txn[c]:
                txn[c] = True
                began[c] = False
                pend[c] = {}
                saves[c] = []
            saves[c].append([a.get("name"), dict(pend[c])])
        elif op == "rollback_to":
            c = route(a, txn)
            idx = find_idx(saves[c], a.get("name"))
            if idx >= 0:
                pend[c] = dict(saves[c][idx][1])
                saves[c] = saves[c][:idx + 1]
        elif op == "release":
            c = route(a, txn)
            idx = find_idx(saves[c], a.get("name"))
            if idx >= 0:
                saves[c] = saves[c][:idx]
                if len(saves[c]) == 0 and not began[c] and txn[c]:
                    flush(pend[c], comm)
                    clear_conn(txn, began, pend, saves, c)
        else:
            c = route(a, txn)
            ch = write_entry(pend[c], comm, txn[c], a.get("key"), a.get("value"), op, cand["conflict"])
            total[c] = total[c] + ch
            if c == "main":
                main_last = ch
    if cand["channel"] == "changes":
        chan = main_last
    elif cand["channel"] == "total_main":
        chan = total["main"]
    else:
        chan = total["main"] + total["other"]
    s = 0
    for v in comm.values():
        s = s + v
    return {"channel": chan, "count": len(comm), "sum": s}


