    out = []
    for conflict in ["ignore", "replace", "upsert"]:
        for channel in ["changes", "total_main", "both"]:
            for trig in [False, True]:
                cand = {"conflict": conflict, "channel": channel, "trigger": trig}
                ok = True
                for r in hist:
                    if r.get("source_id") != source_id:
                        continue
                    obs = r.get("observed")
                    res = simulate(cand, r.get("actions", []))
                    if res["channel"] != obs.get("channel"):
                        ok = False
                    if res["count"] != obs.get("committed_count"):
                        ok = False
                    if res["sum"] != obs.get("committed_sum"):
                        ok = False
                if ok:
                    out.append(cand)
    return out


def investigate(context, acquire):
    hist = acquire("history")
    cands = survivors(hist, context.get("source_id"))
    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = []
    for cand in cands:
        res = simulate(cand, actions)
        if goal == "channel":
            vals.append(res["channel"])
        elif goal == "committed_count":
            vals.append(res["count"])
        else:
            vals.append(res["sum"])
    if len(vals) == 0:
        return {"value": None, "unresolved": True}
    first = vals[0]
    for v in vals:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}

def norm(a):
    c = a.get("connection", "main")
    if c != "other":
        c = "main"
    return c


def route(a, txn):
    if txn.get("main"):
        return "main"
    if txn.get("other"):
        return "other"
    return norm(a)


def view_of(pend, comm):
    v = dict(comm)
    for k in pend:
        if pend[k] is None:
            v.pop(k, None)
        else:
            v[k] = pend[k]
    return v


def write_entry(pend, comm, in_txn, key, value, op, conflict):
    if in_txn:
        exists = key in view_of(pend, comm)
        ch = 0
        if op == "put":
            if exists:
                if conflict == "ignore":
                    ch = 0
                elif conflict == "replace":
                    pend[key] = value
                    ch = 2
                else:
                    pend[key] = value
                    ch = 1
            else:
                pend[key] = value
                ch = 1
        elif op == "update":
            if exists:
                pend[key] = value
                ch = 1
        elif op == "delete":
            if exists:
                pend[key] = None
                ch = 1
        return ch
    exists = key in comm
    ch = 0
    if op == "put":
        if exists:
            if conflict == "ignore":
                ch = 0
            elif conflict == "replace":
                comm[key] = value
                ch = 2
            else:
                comm[key] = value
                ch = 1
        else:
            comm[key] = value
            ch = 1
    elif op == "update":
        if exists:
            comm[key] = value
            ch = 1
    elif op == "delete":
        if exists:
            comm.pop(key)
            ch = 1
    return ch


def flush(pend, comm):
    for k in pend:
        if pend[k] is None:
            comm.pop(k, None)
        else:
            comm[k] = pend[k]


